"""
Task management Flask API with JWT authentication.

Storage: a single flat JSON file (no database). The schema is
initialized on startup by creating the file if it does not exist.

Legacy flat-file data is migrated in place: existing tasks without an
``owner_id`` keep their data and are assigned ``owner_id: null``, and a
``users`` collection is added for JWT-authenticated accounts.

All data access goes through the repository classes in ``repositories``;
route handlers never touch the store directly.
"""

from flask import Flask, request, jsonify, g
from datetime import datetime, timedelta, timezone
import os
from functools import wraps

import jwt
from werkzeug.security import check_password_hash

from celery_tasks import send_notification_email
from repositories import TaskRepository, UserRepository

app = Flask(__name__)

DATA_FILE = os.environ.get("DATA_FILE", "tasks.json")
SECRET_KEY = os.environ.get("SECRET_KEY", "dev-secret-change-me")
JWT_EXPIRES_HOURS = int(os.environ.get("JWT_EXPIRES_HOURS", "24"))

app.config["SECRET_KEY"] = SECRET_KEY


def _current_data_file() -> str:
    return DATA_FILE


task_repository = TaskRepository(_current_data_file)
user_repository = UserRepository(_current_data_file)


def init_store():
    """Initialize the flat-file schema on startup."""
    task_repository._read_store()


# ── Auth helpers ─────────────────────────────────────────────


def verify_user(username: str, password: str) -> dict | None:
    user = user_repository.get_by_username(username)
    if user is None:
        return None
    if not check_password_hash(user["password_hash"], password):
        return None
    return {"id": user["id"], "username": user["username"]}


def notify_task_completed(task: dict, owner_id: int) -> None:
    """Dispatch an async email notification for a completed task.

    Sending is delegated to Celery (non-blocking): the task is queued via
    ``.delay`` and the API response is returned immediately.
    """
    email = user_repository.get_email(owner_id)
    if email is None:
        return
    send_notification_email.delay(email, task["title"])


def _generate_token(user: dict) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user["id"],
        "username": user["username"],
        "iat": now,
        "exp": now + timedelta(hours=JWT_EXPIRES_HOURS),
    }
    return jwt.encode(payload, SECRET_KEY, algorithm="HS256")


def require_auth(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        parts = auth_header.split()
        if len(parts) != 2 or parts[0] != "Bearer":
            return jsonify({"error": "missing or invalid token"}), 401
        token = parts[1]
        try:
            payload = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])
        except jwt.PyJWTError:
            return jsonify({"error": "missing or invalid token"}), 401
        g.user_id = payload.get("sub")
        g.username = payload.get("username")
        if g.user_id is None or user_repository.get(g.user_id) is None:
            return jsonify({"error": "missing or invalid token"}), 401
        return f(*args, **kwargs)

    return wrapper


# ── Routes: auth ─────────────────────────────────────────────

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if username is None or not isinstance(username, str) or not username.strip():
        return jsonify({"error": "username is required"}), 400
    if password is None or not isinstance(password, str) or not password:
        return jsonify({"error": "password is required"}), 400
    username = username.strip()
    try:
        user = user_repository.create(username, password)
    except ValueError:
        return jsonify({"error": "username already taken"}), 409
    return jsonify(user), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({"error": "username and password are required"}), 400
    user = verify_user(username, password)
    if user is None:
        return jsonify({"error": "invalid credentials"}), 401
    token = _generate_token(user)
    return jsonify({"token": token, "username": user["username"], "id": user["id"]})


# ── Routes: tasks (protected) ─────────────────────────────────

@app.route("/tasks", methods=["GET"])
@require_auth
def list_tasks():
    return jsonify(task_repository.list(g.user_id))


@app.route("/tasks", methods=["POST"])
@require_auth
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if title is None or not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    task = task_repository.create(title.strip(), g.user_id)
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@require_auth
def show_task(task_id: int):
    task = task_repository.get(task_id, g.user_id)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@require_auth
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    status = data.get("status")
    if title is not None and not isinstance(title, str):
        return jsonify({"error": "title must be a string"}), 400
    previous = task_repository.get(task_id, g.user_id)
    task = task_repository.update(task_id, g.user_id, title=title, status=status)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    if (
        task.get("status") == "completed"
        and (previous is None or previous.get("status") != "completed")
    ):
        notify_task_completed(task, g.user_id)
    return jsonify(task)


if __name__ == "__main__":
    init_store()
    app.run(debug=True)

"""
Repository-pattern data access layer for the task management API.

All flat-file storage operations live here. Route handlers interact with
repository instances instead of touching the store directly.
"""

import json
import os
import threading
from abc import ABC, abstractmethod
from datetime import datetime

from werkzeug.security import generate_password_hash


class BaseRepository(ABC):
    """Common CRUD operations backed by the flat-file store.

    Subclasses specialise the generic operations for a single collection
    (``tasks`` or ``users``) while sharing the same store plumbing.
    """

    _lock = threading.RLock()
    _collection = None

    def __init__(self, data_file_getter=None):
        self._data_file_getter = data_file_getter or (lambda: "tasks.json")

    @property
    def _data_file(self) -> str:
        return self._data_file_getter()

    # ── store plumbing ─────────────────────────────────────────

    def _empty_store(self) -> dict:
        return {"tasks": [], "users": [], "next_id": 1}

    def _migrate(self, data: dict) -> tuple[dict, bool]:
        """Bring an existing flat-file store up to the current schema.

        Returns ``(data, changed)`` where ``changed`` is True when the
        store was modified and should be written back to disk.
        """
        changed = False
        if not isinstance(data, dict):
            data = {}
            changed = True
        if "tasks" not in data:
            data["tasks"] = []
            changed = True
        if "users" not in data:
            data["users"] = []
            changed = True
        if "next_id" not in data or not isinstance(data["next_id"], int):
            data["next_id"] = 1
            changed = True
        for task in data["tasks"]:
            if not isinstance(task, dict):
                continue
            if "owner_id" not in task:
                task["owner_id"] = None
                changed = True
        return data, changed

    def _read_store(self) -> dict:
        with self._lock:
            try:
                with open(self._data_file, "r", encoding="utf-8") as fh:
                    data = json.load(fh)
            except FileNotFoundError:
                data = self._empty_store()
                self._write_store(data)
                return data
            except (json.JSONDecodeError, ValueError):
                data = self._empty_store()
            data, changed = self._migrate(data)
            if changed:
                self._write_store(data)
            return data

    def _write_store(self, data: dict) -> None:
        tmp = self._data_file + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(data, fh, indent=2)
        os.replace(tmp, self._data_file)

    # ── abstract CRUD ──────────────────────────────────────────

    @abstractmethod
    def get(self, entity_id):
        """Return a single entity by id, or None if it does not exist."""

    @abstractmethod
    def list(self, **filters):
        """Return entities matching the given filters."""

    @abstractmethod
    def create(self, **fields):
        """Persist a new entity and return it."""

    @abstractmethod
    def update(self, entity_id, **fields):
        """Update an entity by id and return it, or None if missing."""

    @abstractmethod
    def delete(self, entity_id):
        """Delete an entity by id and return it, or None if missing."""


class TaskRepository(BaseRepository):
    """CRUD operations for the ``tasks`` collection."""

    _collection = "tasks"

    def get(self, task_id: int, owner_id: int | None = None) -> dict | None:
        data = self._read_store()
        for task in data[self._collection]:
            if task["id"] == task_id and (
                owner_id is None or task.get("owner_id") == owner_id
            ):
                return task
        return None

    def list(self, owner_id: int | None = None) -> list[dict]:
        data = self._read_store()
        tasks = [
            task
            for task in data[self._collection]
            if owner_id is None or task.get("owner_id") == owner_id
        ]
        return sorted(tasks, key=lambda task: task["created_at"], reverse=True)

    def create(self, title: str, owner_id: int) -> dict:
        with self._lock:
            data = self._read_store()
            task = {
                "id": data["next_id"],
                "title": title,
                "status": "pending",
                "created_at": datetime.utcnow().isoformat(),
                "owner_id": owner_id,
            }
            data[self._collection].append(task)
            data["next_id"] += 1
            self._write_store(data)
            return task

    def update(
        self,
        task_id: int,
        owner_id: int,
        title: str | None = None,
        status: str | None = None,
    ) -> dict | None:
        with self._lock:
            data = self._read_store()
            for task in data[self._collection]:
                if task["id"] == task_id and task.get("owner_id") == owner_id:
                    if title is not None:
                        task["title"] = title
                    if status is not None:
                        task["status"] = status
                    self._write_store(data)
                    return task
            return None

    def delete(self, task_id: int, owner_id: int | None = None) -> dict | None:
        with self._lock:
            data = self._read_store()
            collection = data[self._collection]
            for index, task in enumerate(collection):
                if task["id"] == task_id and (
                    owner_id is None or task.get("owner_id") == owner_id
                ):
                    del collection[index]
                    self._write_store(data)
                    return task
            return None


class UserRepository(BaseRepository):
    """CRUD operations for the ``users`` collection."""

    _collection = "users"

    def get(self, user_id: int) -> dict | None:
        data = self._read_store()
        for user in data[self._collection]:
            if user["id"] == user_id:
                return user
        return None

    def get_by_username(self, username: str) -> dict | None:
        data = self._read_store()
        for user in data[self._collection]:
            if user["username"] == username:
                return user
        return None

    def list(self, **filters) -> list[dict]:
        data = self._read_store()
        return list(data[self._collection])

    def create(self, username: str, password: str) -> dict:
        with self._lock:
            data = self._read_store()
            if any(u["username"] == username for u in data[self._collection]):
                raise ValueError("username already taken")
            user = {
                "id": len(data[self._collection]) + 1,
                "username": username,
                "password_hash": generate_password_hash(password),
            }
            data[self._collection].append(user)
            self._write_store(data)
            return {"id": user["id"], "username": user["username"]}

    def update(self, user_id: int, **fields) -> dict | None:
        with self._lock:
            data = self._read_store()
            for user in data[self._collection]:
                if user["id"] == user_id:
                    for key, value in fields.items():
                        user[key] = value
                    self._write_store(data)
                    return user
            return None

    def delete(self, user_id: int) -> dict | None:
        with self._lock:
            data = self._read_store()
            collection = data[self._collection]
            for index, user in enumerate(collection):
                if user["id"] == user_id:
                    del collection[index]
                    self._write_store(data)
                    return user
            return None

    def get_email(self, user_id: int) -> str | None:
        """Resolve an owner's email address (falling back to a derived address)."""
        user = self.get(user_id)
        if user is None:
            return None
        return user.get("email") or f"{user['username']}@example.com"

